# Look up #office-bellevue channel ID via IS resources
uip is resources run list "uipath-salesforce-slack" "channels" --connection-id "849e85d8-1aa9-4d52-8bbd-20041c8f05d8" --output json 2>/dev/null | python3 -c "
import json, sys
data = json.load(sys.stdin)
items = data.get('Data', [])
if isinstance(items, list):
    for item in items:
        name = item.get('name','') or item.get('Name','')
        id_ = item.get('id','') or item.get('Id','')
        if 'office' in name.lower() or 'bellevue' in name.lower():
            print('FOUND:', id_, name)
    print('Total items:', len(items))
    if items: print('Sample:', json.dumps(items[0], indent=2))
else:
    print(json.dumps(data, indent=2)[:2000])
" 2>/dev/null || echo "error"

